/**
 * @description End-to-end tests with records for the REST endpoints: inbound call, status and the callback. Validation
 * and mapping are covered without data in IntegrationHubUnitTestInbound.
 */
@IsTest
private class IntegrationHubInboundTest {

    private static String requestId;

    @TestSetup
    static void setup() {
        IntegrationHubTestData.setupAll();
    }

    private static RestResponse call(String method, String path, String body) {
        RestRequest req = new RestRequest();
        req.requestURI = '/services/apexrest/integrationhub/v1/' + path;
        req.httpMethod = method;
        req.requestBody = body == null ? null : Blob.valueOf(body);
        if (requestId != null) {
            req.headers.put('X-Request-Id', requestId);
        }
        RestContext.request = req;
        RestContext.response = new RestResponse();
        if (method == 'POST') {
            IntegrationHubInboundApi.receive();
        } else if (method == 'PATCH') {
            IntegrationHubInboundApi.callback();
        } else {
            IntegrationHubInboundApi.status();
        }
        return RestContext.response;
    }

    private static Map<String, Object> bodyOf(RestResponse res) {
        return (Map<String, Object>) JSON.deserializeUntyped(res.responseBody.toString());
    }

    @IsTest
    static void inboundEndToEnd() {
        System.runAs(IntegrationHubTestData.admin()) {
            requestId = 'req-1';
            RestResponse first = call('POST', IntegrationHubTestData.IN_KEY, '{"name":"Acme Inbound"}');
            Assert.areEqual(200, first.statusCode, 'the handler succeeded');
            Assert.isNotNull(bodyOf(first).get('recordId'), 'the new record Id is returned');
            RestResponse again = call('POST', IntegrationHubTestData.IN_KEY, '{"name":"Acme Inbound"}');
            Assert.areEqual('true', again.headers.get('Idempotent-Replay'), 'a repeat is marked as a replay');
            requestId = null;
            Assert.areEqual(500, call('POST', IntegrationHubTestData.IN_KEY, '{"mode":"boom"}').statusCode, 'a handler crash is 500');
            List<IH_Transaction__c> txns = IntegrationHubTestData.transactions(IntegrationHubTestData.IN_KEY);
            Assert.areEqual(2, txns.size(), 'the repeat did not run again');
            Assert.areEqual(200, call('GET', 'status/' + txns[0].Id, null).statusCode, 'status of a known transaction');
        }
        System.runAs(IntegrationHubTestData.reader()) {
            Assert.areEqual(403, call('POST', IntegrationHubTestData.IN_KEY, '{}').statusCode, 'not the inbound user');
        }
    }

    @IsTest
    static void callbackEndToEnd() {
        System.runAs(IntegrationHubTestData.admin()) {
            IH_Transaction__c ok = IntegrationHubTestData.newTransaction(IntegrationHubTestData.OUT_KEY, 'Sent');
            RestResponse res = call('PATCH', 'callback/' + ok.Id, '{"status":"accepted","reference":"MAC-1"}');
            Assert.areEqual(200, res.statusCode, 'callback accepted');
            IH_Transaction__c after = IntegrationHubTestData.transactions(IntegrationHubTestData.OUT_KEY)[0];
            Assert.areEqual('Success', after.Status__c, 'ACCEPTED means Success');
            Assert.areEqual('MAC-1', after.External_Reference_Id__c, 'the reference is stored');
            Assert.areEqual('CALLBACK', after.Correlation_Id__c, 'the response handler ran for the callback');
            IH_Transaction__c bad = IntegrationHubTestData.newTransaction(IntegrationHubTestData.CALLBACK_KEY, 'Sent');
            RestResponse rejected = call('PATCH', 'callback/' + bad.Id, '{"status":"REJECTED","message":"Duplicate"}');
            Assert.areEqual('Failed', bodyOf(rejected).get('status'), 'REJECTED means Failed');
            Assert.areEqual(404, call('PATCH', 'callback/' + IntegrationHubTestData.eventByKey(IntegrationHubTestData.OUT_KEY).Id, '{}').statusCode,
                'an Id of another object is not found');
        }
    }
}
